<?php require __DIR__.'/bootstrap.php';$where=['1=1'];$args=[];if($q=clean($_GET['q']??'')){$where[]='title LIKE ?';$args[]="%$q%";}if($r=clean($_GET['relevance']??'')){$where[]='relevance_status=?';$args[]=$r;}$st=db()->prepare('SELECT * FROM news WHERE '.implode(' AND ',$where).' ORDER BY published_at DESC,discovered_at DESC LIMIT 200');$st->execute($args);respond(['items'=>$st->fetchAll()]);
